primaryQuery:
run: order_items -> {
  group_by: user_id
  aggregate: orders is count(order_id)
} -> {
  aggregate: top_customers is count() { where: orders > 10 }
}

verifyQuery:
run: order_items -> {
  group_by: user_id, order_id
} -> {
  group_by: user_id
  aggregate: orders is count()
} -> {
  aggregate: top_customers is count() { where: orders > 10 }
}
